func tl0(a *tslabs, v any) []Misc {
	a.stepWork()
	if v == nil {
		return nil
	}
	n, _ := v.(*tnode)
	if n == nil {
		return []Misc{} // another node (an Error), as conversion makes an empty list of it
	}
	out := astSlice(&a.tl0Chunk, len(n.kids))
	for i, c := range n.kids {
		a.stepWork()
		out[i] = tAs[Misc](tpub(c))
	}
	return out
}

